// Simulation state and player
const layers=[{name:'Surface Soil',depth:0,color:0x8e7958,resource:'TOPSOIL',reward:0},{name:'Dirt & Clay',depth:30,color:0x8a6247,resource:'CLAY SAMPLE',reward:35},{name:'Limestone',depth:90,color:0xb5aa88,resource:'LIMESTONE',reward:55},{name:'Stone',depth:180,color:0x737a78,resource:'STONE CORE',reward:75},{name:'Coal Deposits',depth:360,color:0x3f4544,resource:'COAL SEAM',reward:120},{name:'Iron Deposits',depth:600,color:0x885d4d,resource:'IRON ORE',reward:170},{name:'Gold Deposits',depth:1000,color:0xb88b35,resource:'GOLD VEIN',reward:260},{name:'Diamond Deposits',depth:1500,color:0x49a9a9,resource:'DIAMOND',reward:420},{name:'Deep Mantle',depth:2300,color:0x9c4d40,resource:'MANTLE SAMPLE',reward:600},{name:'Magma Zone',depth:3400,color:0xed5527,resource:'MAGMA GLASS',reward:850},{name:"Earth's Outer Core",depth:4700,color:0xe28332,resource:'CORE ALLOY',reward:1300},{name:"Earth's Inner Core",depth:6000,color:0xf7cb6d,resource:'INNER CORE',reward:2500}];
const state={money:480,depth:0,oil:100,oilMax:100,can:0,canSize:60,barrels:0,drilling:false,yaw:0,pitch:0,player:new THREE.Vector3(0,0,14),velY:0,onGround:true,sprint:false,jumpQueued:false,layer:0,upgrades:{power:0,speed:0,capacity:0,efficiency:0,heat:0,durability:0},modal:'',won:false};
const upgradeData=[['power','Drill power','Break tougher strata · +25% yield',180],['speed','Drill speed','Increase the rate of descent',220],['capacity','Oil capacity','Rig reservoir +50 L per level',240],['efficiency','Oil efficiency','Consume 15% less oil',200],['heat','Heat resistance','Withstand mantle & magma heat',320],['durability','Drill durability','Reduce wear in deep rock',280]];
const keys={};let joy={x:0,y:0,id:null},lookTouch=null,lastFrame=performance.now(),toastTimer=0,interactTarget=null,drillTime=0,particles=[];const $=id=>document.getElementById(id);
const prompt=$('prompt'),promptText=$('promptText'),reticle=$('reticle'),toast=$('toast'),backdrop=$('modalBackdrop'),itemList=$('itemList');
function showToast(message){toast.innerHTML=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2500)}
function layerAt(depth){let n=0;for(let i=0;i<layers.length;i++)if(depth>=layers[i].depth)n=i;return n}
function showModal(type){state.modal=type;backdrop.classList.add('open');itemList.innerHTML='';let sub='',note='';if(type==='shop'){ $('modalKicker').textContent='FIELD SUPPLY / COUNTER';$('modalTitle').textContent='Oil & equipment';sub='Pick up a sealed oil can here, then carry it to the service hatch at the top of the rig.';note=`Depot stock · ${Math.max(0,8-state.barrels)} oil cans remaining`;
addItem('Oil can · 60 L','Portable sealed supply · carry one at a time','$ 80',state.money<80||state.can>0||state.barrels>=8,()=>{state.money-=80;state.can+=60;state.barrels++;showToast('Oil can collected — <em>60 L</em> in hand');closeModal();updateUI()});
addItem('Bulk drum · +50 L capacity','Permanent rig reservoir expansion','$ 260',state.money<260||state.upgrades.capacity>=4,()=>{state.money-=260;state.upgrades.capacity++;state.oilMax+=50;state.oil=Math.min(state.oil+25,state.oilMax);showToast('Reservoir expanded — <em>+50 L capacity</em>');showModal('shop');updateUI()});
addItem('Sell current discovery','Trade the latest recovered sample',`$ ${Math.max(0,state.lastReward||0)}`,!state.lastReward,()=>{state.money+=state.lastReward;showToast(`Sample sold — <em>+$${state.lastReward}</em>`);state.lastReward=0;showModal('shop');updateUI()});
}else if(type==='lab'){$('modalKicker').textContent='FIELD SCIENCE / UPGRADE BAY';$('modalTitle').textContent='Rig development';sub='Research equipment improvements. Upgrades stack and are applied immediately.';note=`AVAILABLE FUNDS · $${state.money}`;
for(const [id,title,desc,base] of upgradeData){const lv=state.upgrades[id],cost=Math.round(base*(1+lv*.72));addItem(`${title} · LV ${lv}`,desc,`$ ${cost}`,state.money<cost||lv>=5,()=>{state.money-=cost;state.upgrades[id]++;if(id==='capacity'){state.oilMax+=50;state.oil=Math.min(state.oil+25,state.oilMax)}showToast(`${title} upgraded — <em>LV ${state.upgrades[id]}</em>`);showModal('lab');updateUI()})}
}else if(type==='refill'){$('modalKicker').textContent='RIG SERVICE / UPPER DECK';$('modalTitle').textContent='Refill reservoir';sub='Connect your carried can to the open service hatch. The rig must be idle while refilling.';note=state.can>0?`SEALED SUPPLY · ${state.can} L IN HAND`:'No oil can in hand — visit the depot.';addItem('Pour carried oil','Transfer oil from your can into the reservoir',state.can>0?`+ ${Math.min(state.can,state.oilMax-state.oil)} L`:'EMPTY',state.can<=0||state.oil>=state.oilMax||state.drilling,()=>{const amount=Math.min(state.can,state.oilMax-state.oil);state.can-=amount;state.oil+=amount;showToast(`Oil poured — <em>+${amount} L</em>`);showModal('refill');updateUI()})}
$('modalSub').textContent=sub;$('modalNote').textContent=note;backdrop.dataset.type=type}
function addItem(title,desc,price,disabled,fn){const row=document.createElement('div');row.className='item';const left=document.createElement('div');left.innerHTML=`<div class="item-title">${title}</div><div class="item-desc">${desc}</div>`;const btn=document.createElement('button');btn.className='buy';btn.textContent=price;btn.disabled=disabled;btn.onclick=fn;row.append(left,btn);itemList.append(row)}
function closeModal(){state.modal='';backdrop.classList.remove('open')}$('closeModal').onclick=closeModal;backdrop.addEventListener('pointerdown',e=>{if(e.target===backdrop)closeModal()});
function updateUI(){const layer=layers[state.layer];$('money').textContent=Math.floor(state.money).toLocaleString();$('depth').textContent=Math.floor(state.depth).toLocaleString();$('layerName').textContent=layer.name.toUpperCase();$('oil').textContent=Math.floor(state.oil);$('oilMax').textContent=state.oilMax;$('oilFill').style.width=`${Math.max(0,state.oil/state.oilMax*100)}%`;$('oilFill').style.background=state.oil<20?'#dd6652':'linear-gradient(90deg,#d09b58,#f4c578)';$('status').textContent=state.won?'CORE REACHED':state.drilling?(state.oil>0?'DRILLING':'OUT OF OIL'):'STANDBY';$('status').style.color=state.drilling&&state.oil>0?'#c8f169':state.oil<=0?'#ef816b':'';const pct=Math.min(100,state.depth/6371*100);$('progress').style.width=`${pct}%`;$('percent').textContent=`${pct.toFixed(1)}%`;$('rate').textContent=state.drilling?`${(4.5+state.upgrades.speed*2.8).toFixed(1)} m/s`:'0 m/s';$('resourceLabel').textContent=state.layer?layers[state.layer].resource:'NO DISCOVERY';$('hand').textContent=state.can>0?`OIL CAN · ${state.can} L`:'EMPTY HANDS';const mission=state.can>0?['Deliver supply to the rig','Climb the yellow service stairs and refill at the open hatch.',`${state.can} L READY TO POUR`]:state.oil<15?['Resupply the rig','Pick up oil at the depot counter, then bring it to the upper service deck.','OIL CRITICAL']:state.depth===0?['Secure the first supply','Visit the oil depot and pick up a can. Carry it to the rig\'s elevated service deck to refill.','0 / 1 SUPPLY SECURED']:state.drilling?['Keep descending','Watch oil levels and sell newly recovered samples to fund your next run.',`${Math.floor(pct)}% TO CORE`]:['Continue the descent','Operate the rig, and manage supplies as the geology gets tougher.',`${Math.floor(pct)}% TO CORE`];$('missionTitle').textContent=state.won?'Mission complete':mission[0];$('missionText').textContent=state.won?'Earth’s inner core reached. The Deepworks expedition is yours.':mission[1];$('missionFoot').textContent=state.won?'INNER CORE REACHED':mission[2]}
function setTarget(){const p=state.player;const dist=(x,z)=>Math.hypot(p.x-x,p.z-z);interactTarget=null;let targetText='';if(dist(22,2.1)<4.2){interactTarget='shop';targetText='OPEN SUPPLY COUNTER'}else if(dist(12,2.1)<4.2){interactTarget='lab';targetText='OPEN UPGRADE BAY'}else if(Math.hypot(p.x,p.z+1)<2.2&&p.y>4.15){interactTarget='refill';targetText='REFILL OIL RESERVOIR'}else if(dist(0,0)<5.5){interactTarget='rig';targetText=state.drilling?'SHUT DOWN DRILL':'START DRILL'}prompt.classList.toggle('show',!!interactTarget);promptText.textContent=targetText;reticle.textContent=interactTarget==='refill'?'SERVICE HATCH':interactTarget==='shop'?'SUPPLY COUNTER':interactTarget==='lab'?'RESEARCH LAB':interactTarget==='rig'?'DRILL CONTROLS':''}
function interact(){if(state.modal){closeModal();return}setTarget();if(!interactTarget){showToast('Move closer to a marked station');return}if(interactTarget==='shop')showModal('shop');if(interactTarget==='lab')showModal('lab');if(interactTarget==='refill'){if(state.drilling){showToast('Shut down the drill before refilling');return}showModal('refill')}if(interactTarget==='rig')toggleDrill()}
function toggleDrill(){if(state.won)return;if(state.drilling){state.drilling=false;showToast('Rig shut down — <em>safe to service</em>')}else if(state.oil<=0){showToast('Reservoir empty — <em>bring an oil can to the service hatch</em>')}else{state.drilling=true;showToast('Drill engaged — <em>descent underway</em>')}updateUI()}
function action(){if(state.modal)return;if(interactTarget==='rig'){toggleDrill();return}if(interactTarget==='shop'||interactTarget==='lab'||interactTarget==='refill'){interact();return}if(state.drilling)toggleDrill();else showToast('Find the rig controls or press E nearby')}
function jump(){if(state.onGround){state.velY=6.2;state.onGround=false}}
function setKeys(e,down){keys[e.code]=down;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(down&&e.code==='KeyE')interact();if(down&&e.code==='Space')jump();if(down&&e.code==='Escape')closeModal();if(down&&e.code==='Enter'&&state.modal==='')action()}
window.addEventListener('keydown',e=>setKeys(e,true));window.addEventListener('keyup',e=>setKeys(e,false));
renderer.domElement.addEventListener('click',()=>{if(state.modal)return;if(innerWidth>700&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.();action()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!state.modal){state.yaw-=e.movementX*.0022;state.pitch=Math.max(-1.35,Math.min(1.35,state.pitch-e.movementY*.0022))}});
// Touch controls: floating joystick + independent right-side look zone
const joyEl=$('joystick'),knob=$('joyKnob');function joyMove(e){const r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),k=Math.min(max,d),a=Math.atan2(dy,dx);joy.x=Math.cos(a)*k/max;joy.y=Math.sin(a)*k/max;knob.style.left=`calc(50% + ${joy.x*max}px)`;knob.style.top=`calc(50% + ${joy.y*max}px)`}
joyEl.addEventListener('pointerdown',e=>{joy.id=e.pointerId;joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(joy.id===e.pointerId)joyMove(e)});function joyEnd(e){if(joy.id===e.pointerId){joy.id=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}}joyEl.addEventListener('pointerup',joyEnd);joyEl.addEventListener('pointercancel',joyEnd);
renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&e.clientX>innerWidth*.36){lookTouch={id:e.pointerId,x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(lookTouch&&lookTouch.id===e.pointerId&&!state.modal){state.yaw-=(e.clientX-lookTouch.x)*.006;state.pitch=Math.max(-1.25,Math.min(1.25,state.pitch-(e.clientY-lookTouch.y)*.006));lookTouch.x=e.clientX;lookTouch.y=e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(lookTouch?.id===e.pointerId)lookTouch=null});
$('jumpBtn').addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('sprintBtn').addEventListener('pointerdown',e=>{e.preventDefault();state.sprint=true;$('sprintBtn').classList.add('active')});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('sprintBtn').addEventListener(ev,()=>{state.sprint=false;$('sprintBtn').classList.remove('active')}));$('interactBtn').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('actionBtn').addEventListener('pointerdown',e=>{e.preventDefault();action()});

