const material=(c,r=.8,m=0)=>new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m}),M={ground:material(0x716d58),pad:material(0x3c4744),concrete:material(0x888d82),steel:material(0x3b474b,.42,.7),silver:material(0x778487,.4,.65),yellow:material(0xe4aa48,.48,.25),dark:material(0x182122,.6,.35),glass:material(0x53787a,.2,.3),white:material(0xd8d9cb),green:material(0x425b43),wood:material(0x67583e),orange:material(0xd97744),lime:material(0xc8f169)};
