$('operate').onpointerdown=e=>{e.preventDefault();action()};
// First-person movement, walkable service stairs, drilling simulation, and rendering.
const clock=new THREE.Clock();
function floorHeight(x,z,feetY){
  let h=0;
  // The yellow stair run rises from the yard to the service deck.
  if(z>-.95&&z<.95&&x>2.45&&x<6.9) h=Math.max(h,.55+(6.6-x)/3.9*4.55);
  // The hatch sits on the upper deck; only snap onto it from the stairs or while already up.
  if(x>-.95&&x<3.55&&Math.abs(z)<1.65&&(feetY>4.65||h>4.5)) h=Math.max(h,5.38);
  return h;
}
function blocked(x,z){
  if(x < -68 || x > 68 || z < -88 || z > 48) return true;
  // Building shells; keep their front service entrances clear.
  for(const bx of [12,22]) if(Math.abs(x-bx)<4.45&&z>-6.2&&z<2.1&&!(Math.abs(x-(bx-2))<.95&&z>1.1)) return true;
  return false;
}
function layerRate(){
  const i=state.layer, power=state.up.power;
  const hardness=[1,1,.92,.82,.72,.62,.52,.43,.34,.27,.22,.18][i]||.18;
  return (4.5+state.up.speed*2.8)*(hardness+power*.055);
}
function layerChange(next){
  state.layer=next;
  const entry=layers[next];
  toast(`<b>${entry[0]}</b> reached · sample recovered`);
  state.lastReward=Math.max(state.lastReward,entry[4]);
  scene.fog.color.setHex(next>=9?0x79463d:next>=6?0x73705d:0x9bb7b9);
  scene.background.setHex(next>=9?0x79463d:next>=6?0x73705d:0x9bb7b9);
  if(next>=11){state.won=true;state.drilling=false;toast('INNER CORE REACHED · <b>Expedition complete</b>')}
}
function updateWorld(dt){
  const canMove=!state.modal;
  let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-joyY;
  let side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joyX;
  const len=Math.hypot(forward,side)||1;forward/=len;side/=len;
  const sprint=state.sprint||keys.ShiftLeft||keys.ShiftRight;
  const speed=(sprint?8.2:5.2)*(state.can?.78:1);
  if(canMove&&(Math.abs(forward)+Math.abs(side)>.01)){
    const dx=(-Math.sin(state.yaw)*forward+Math.cos(state.yaw)*side)*speed*dt;
    const dz=(-Math.cos(state.yaw)*forward-Math.sin(state.yaw)*side)*speed*dt;
    if(!blocked(state.pos.x+dx,state.pos.z))state.pos.x+=dx;
    if(!blocked(state.pos.x,state.pos.z+dz))state.pos.z+=dz;
  }
  const floor=floorHeight(state.pos.x,state.pos.z,state.pos.y);
  if(state.grounded){
    const nextFloor=floorHeight(state.pos.x,state.pos.z,state.pos.y);
    if(nextFloor<=state.pos.y+.45)state.pos.y=nextFloor;
    else {state.grounded=false;state.vy=0}
  }
  if(!state.grounded){state.vy-=17*dt;state.pos.y+=state.vy*dt;const landing=floorHeight(state.pos.x,state.pos.z,state.pos.y);if(state.pos.y<=landing){state.pos.y=landing;state.vy=0;state.grounded=true}}
  if(state.pos.y<0){state.pos.y=0;state.vy=0;state.grounded=true}
  camera.position.set(state.pos.x,state.pos.y+1.62,state.pos.z);
  camera.rotation.set(state.pitch,state.yaw,0,'YXZ');
  setTarget();
  if(state.drilling){
    let rate=layerRate();
    const heatFactor=state.layer>=9?Math.max(.35,1-state.up.heat*.12):1;
    state.depth+=rate*dt;
    state.oil=Math.max(0,state.oil-dt*(.09/(1+state.up.efficiency*.15))*heatFactor);
    const newLayer=layerAt(state.depth);
    if(newLayer!==state.layer)layerChange(newLayer);
    if(state.depth>=6371){state.depth=6371;state.layer=11;state.won=true;state.drilling=false}
    if(state.oil<=0){state.drilling=false;toast('Reservoir empty · <b>service the rig to continue</b>')}
  }
  drill.rotation.y+=dt*(state.drilling?8:1.2);
  drill.position.y=-1.8-Math.min(4,state.depth*.012);
  if(state.drilling){rockTimer+=dt;if(rockTimer>.16){rockTimer=0;const spark=new THREE.Mesh(new THREE.SphereGeometry(.055,6,6),M.yellow);spark.position.set((Math.random()-.5)*1.5,.4+Math.random()*1.5,(Math.random()-.5)*1.5);rig.add(spark);particles.push({mesh:spark,life:.45})}}
  for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.mesh.position.y+=dt*1.7;if(p.life<=0){rig.remove(p.mesh);p.mesh.geometry.dispose();particles.splice(i,1)}}
}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-prev)/1000||0);prev=now;updateWorld(dt);update();renderer.render(scene,camera)}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))}
window.addEventListener('resize',resize);
$('prompt').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
update();setTarget();requestAnimationFrame(frame);
</script></body></html>

